async function generateSpeechAudio(text, voice) {
  try {
    const tts = new import_msedge_tts.MsEdgeTTS();
    await tts.setMetadata(voice, import_msedge_tts.OUTPUT_FORMAT.AUDIO_24KHZ_48KBITRATE_MONO_MP3);
    const { audioStream } = tts.toStream(text);
    return await new Promise((resolve, reject) => {
      const chunks = [];
      audioStream.on("data", (d5) => chunks.push(d5));
      audioStream.on("end", () => resolve(Buffer.concat(chunks)));
      audioStream.on("error", reject);
    });
  } catch (err) {
    console.warn("TTS generation failed:", err.message);
    return null;
  }
}
async function handler(event) {
  const headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS"
  };
  try {
    const path = event.rawPath || event.path || "/";
    const method = (event.requestContext?.http?.method || event.httpMethod || "GET").toUpperCase();
    if (method === "OPTIONS") {
      return { statusCode: 200, headers, body: "" };
    }
    if (path.endsWith("/setup") || path.endsWith("/setup/")) {
      return {
        statusCode: 200,
        headers,
        body: JSON.stringify({ ready: true, python: true, ffmpeg: true, voices: true, cloud: "amplify" })
      };
    }
    if (path.endsWith("/recipes") || path.endsWith("/recipes/")) {
      return {
        statusCode: 200,
        headers,
        body: JSON.stringify({ recipes: RECIPES, voices: VOICES, formats: ["16:9", "9:16"], busy: false })
      };
    }
    if (path.endsWith("/plan") && method === "POST") {
      let body = {};
      try {
        body = JSON.parse(event.body || "{}");
      } catch {
      }
      const isTamil = body.voice === "ta-IN-PallaviNeural";
      const selectedVoice = isTamil ? "ta-IN-PallaviNeural" : body.voice || "en-US-JennyNeural";
      const matched = matchRecipeFromPrompt(body.prompt);
      let planData;
      if (matched) {
        planData = {
          title: isTamil ? matched.titleTa : matched.titleEn,
          recipeId: matched.id,
          ingredients: isTamil ? matched.ingredientsTa : matched.ingredientsEn,
          steps: isTamil ? matched.stepsTa : matched.stepsEn
        };
      } else {
        const dishTitle = cleanRecipeTitle(body.prompt);
        planData = getCustomRecipePlan(dishTitle, isTamil);
      }
      let audioUrl = null;
      try {
        const fullSpeechText = planData.steps.map((s2) => s2.text).join(" ");
        const audioBuffer = await generateSpeechAudio(fullSpeechText, selectedVoice);
        if (audioBuffer) {
          const audioKey = `audio/preview-${Date.now()}-${Math.random().toString(36).slice(2, 7)}.mp3`;
          await s3.send(new import_client_s313.PutObjectCommand({
            Bucket: bucketName,
            Key: audioKey,
            Body: audioBuffer,
            ContentType: "audio/mpeg"
          }));
          audioUrl = `https://${bucketName}.s3.${region}.amazonaws.com/${audioKey}`;
        }
      } catch (e5) {
        console.warn("Preview speech notice:", e5.message);
      }
      return {
        statusCode: 200,
        headers,
        body: JSON.stringify({
          title: planData.title,
          recipe: planData.recipeId,
          generic: false,
          source: isTamil ? "Tamil AI Lesson" : "AI Recipe Plan",
          steps: planData.steps.map((s2) => ({ key: s2.key, text: s2.text, action: s2.action })),
          ingredients: planData.ingredients.map((i5) => i5.name),
          audioUrl
        })
      };
    }
    if (path.endsWith("/generate") && method === "POST") {
      let body = {};
      try {
        body = JSON.parse(event.body || "{}");
      } catch {
      }
      const { prompt, voice, format: format2 } = body;
      const isTamil = voice === "ta-IN-PallaviNeural";
      const selectedVoice = isTamil ? "ta-IN-PallaviNeural" : voice || "en-US-JennyNeural";
      const selectedFormat = format2 === "9:16" ? "9:16" : "16:9";
      const matched = matchRecipeFromPrompt(prompt);
      let planData;
      if (matched) {
        planData = {
          title: isTamil ? matched.titleTa : matched.titleEn,
          recipeId: matched.id,
          ingredients: isTamil ? matched.ingredientsTa : matched.ingredientsEn,
          steps: isTamil ? matched.stepsTa : matched.stepsEn
        };
      } else {
        const dishTitle = cleanRecipeTitle(prompt);
        planData = getCustomRecipePlan(dishTitle, isTamil);
      }
      const lastStepEnd = planData.steps[planData.steps.length - 1]?.end || 36;
      const duration = Math.max(30, Math.min(90, Math.ceil(lastStepEnd)));
      console.log(`Generating narration for: ${planData.title} in ${selectedVoice} (duration ~${duration}s)`);
      const fullSpeechText = planData.steps.map((s2) => s2.text).join(" ");
      const audioBuffer = await generateSpeechAudio(fullSpeechText, selectedVoice);
      let audioUrl = null;
      if (audioBuffer) {
        try {
          const audioKey = `audio/${Date.now()}-${Math.random().toString(36).slice(2, 7)}.mp3`;
          await s3.send(new import_client_s313.PutObjectCommand({
            Bucket: bucketName,
            Key: audioKey,
            Body: audioBuffer,
            ContentType: "audio/mpeg"
          }));
          audioUrl = `https://${bucketName}.s3.${region}.amazonaws.com/${audioKey}`;
        } catch (err) {
          console.warn("Audio upload warning:", err.message);
        }
      }
      const plan = {
        recipe: planData.recipeId,
        title: planData.title,
        format: selectedFormat,
        voice: selectedVoice,
        ingredients: planData.ingredients,
        actions: planData.steps
      };
      const lesson = {
        duration,
        steps: planData.steps,
        captions: planData.steps.map((s2) => ({ start: s2.start, end: s2.end, text: s2.text }))
      };
      const isPortrait = selectedFormat === "9:16";
      const width = isPortrait ? 1080 : 1920;
      const height = isPortrait ? 1920 : 1080;
      const fps = 30;
      if (process.env.MODAL_ENDPOINT) {
        try {
          const s3Key = `videos/modal-${Date.now()}-${plan.recipe}.mp4`;
          const modalRes = await fetch(process.env.MODAL_ENDPOINT, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              recipe: plan.recipe,
              title: plan.title,
              prompt: fullSpeechText,
              voice: selectedVoice,
              format: selectedFormat,
              duration,
              s3_bucket: bucketName,
              s3_key: s3Key
            })
          });
          if (modalRes.ok) {
            const modalData = await modalRes.json();
            return {
              statusCode: 200,
              headers,
              body: JSON.stringify({
                id: `modal:${Date.now()}`,
                status: "complete",
                progress: 100,
                videoUrl: modalData.videoUrl,
                message: isTamil ? "\u0B9F\u0BBF\u0BB8\u0BCD\u0BA9\u0BBF/\u0BAA\u0BBF\u0B95\u0BCD\u0B9A\u0BBE\u0BB0\u0BCD 3D \u0B95\u0BBE\u0BB0\u0BCD\u0B9F\u0BCD\u0B9F\u0BC2\u0BA9\u0BCD \u0BB5\u0BC0\u0B9F\u0BBF\u0BAF\u0BCB \u0BA4\u0BAF\u0BBE\u0BB0\u0BBE\u0B95\u0BBF\u0BB5\u0BBF\u0B9F\u0BCD\u0B9F\u0BA4\u0BC1!" : "3D Pixar-style cooking video rendered on Serverless GPU and ready to stream!"
              })
            };
          }
        } catch (err) {
          console.warn("Modal serverless execution notice:", err.message);
        }
      }
      if (process.env.AI_DIFFUSION_WORKER_URL) {
        try {
          const s3Key = `videos/ai-diffusers-${Date.now()}-${plan.recipe}.mp4`;
          const diffRes = await fetch(`${process.env.AI_DIFFUSION_WORKER_URL}/generate`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              recipe: plan.recipe,
              title: plan.title,
              prompt: fullSpeechText,
              voice: selectedVoice,
              format: selectedFormat,
              duration,
              s3_bucket: bucketName,
              s3_key: s3Key
            })
          });
          if (diffRes.ok) {
            const diffData = await diffRes.json();
            return {
              statusCode: 202,
              headers,
              body: JSON.stringify({
                id: `diffusers:${diffData.jobId}`,
                recipe: plan.recipe,
                title: plan.title,
                format: selectedFormat,
                voice: selectedVoice,
                status: "rendering",
                progress: 10,
                message: isTamil ? `\u0B9A\u0BC6\u0B83\u0BAA\u0BCD \u0BAE\u0BBE\u0BAF\u0BBE Disney/Pixar AI \u0BB5\u0BC0\u0B9F\u0BBF\u0BAF\u0BCB\u0BB5\u0BC8 \u0B89\u0BB0\u0BC1\u0BB5\u0BBE\u0B95\u0BCD\u0B95\u0BC1\u0B95\u0BBF\u0BB1\u0BBE\u0BB0\u0BCD...` : `Rendering Disney/Pixar 3D animation with Hugging Face Diffusers...`
              })
            };
          }
        } catch (err) {
          console.warn("Diffusers worker notice:", err.message);
        }
      }
      try {
        const { renderId } = await renderMediaOnLambda({
          region,
          functionName,
          serveUrl,
          composition: "LifeMotionCooking",
          inputProps: {
            plan,
            lesson,
            audioFile: audioUrl,
            fps,
            width,
            height,
            durationInFrames: duration * fps
          },
          concurrency: 2,
          maxRetries: 3,
          codec: "h264",
          privacy: "public"
        });
        return {
          statusCode: 202,
          headers,
          body: JSON.stringify({
            id: `${bucketName}:${renderId}`,
            recipe: plan.recipe,
            title: plan.title,
            format: selectedFormat,
            voice: selectedVoice,
            status: "rendering",
            progress: 5,
            message: isTamil ? `\u0B9A\u0BC6\u0B83\u0BAA\u0BCD \u0BAE\u0BBE\u0BAF\u0BBE "${planData.title}" \u0B95\u0BBE\u0BB0\u0BCD\u0B9F\u0BCD\u0B9F\u0BC2\u0BA9\u0BCD \u0BB5\u0BC0\u0B9F\u0BBF\u0BAF\u0BCB\u0BB5\u0BC8 \u0B89\u0BB0\u0BC1\u0BB5\u0BBE\u0B95\u0BCD\u0B95\u0BC1\u0B95\u0BBF\u0BB1\u0BBE\u0BB0\u0BCD...` : `Chef Maya is animating the cooking video for ${plan.title}...`
          })
        };
      } catch (renderError) {
        console.error("Lambda render launch error:", renderError);
        return {
          statusCode: 500,
          headers,
          body: JSON.stringify({
            error: `Video generation failed on AWS Lambda: ${renderError.message || String(renderError)}. Please try again.`
          })
        };
      }
    }
    if (path.includes("/jobs")) {
      const rawId = path.split("/").pop();
      if (rawId.startsWith("diffusers:") && process.env.AI_DIFFUSION_WORKER_URL) {
        const jobId = rawId.replace("diffusers:", "");
        try {
          const workerRes = await fetch(`${process.env.AI_DIFFUSION_WORKER_URL}/jobs/${jobId}`);
          if (workerRes.ok) {
            const workerData = await workerRes.json();
            return {
              statusCode: 200,
              headers,
              body: JSON.stringify({ id: rawId, ...workerData })
            };
          }
        } catch (e5) {
          console.warn("Diffusers job poll notice:", e5.message);
        }
      }
      let bName = bucketName;
      let renderId = rawId;
      if (rawId.includes(":")) {
        const parts = rawId.split(":");
        bName = parts[0];
        renderId = parts[1];
      }
      try {
        const progress = await getRenderProgress({
          renderId,
          bucketName: bName,
          functionName,
          region
        });
        if (progress.fatalErrorEncountered) {
          return {
            statusCode: 200,
            headers,
            body: JSON.stringify({
              id: rawId,
              status: "failed",
              progress: 0,
              message: progress.errors?.[0]?.message || "Cloud render failed."
            })
          };
        }
        if (progress.done) {
          let finalUrl = progress.outputFile;
          try {
            let outputKey = `renders/${renderId}/out.mp4`;
            if (progress.outputFile) {
              try {
                const parsed = new URL(progress.outputFile);
                let pathPart = parsed.pathname.replace(/^\/+/, "");
                if (pathPart.startsWith(bName + "/")) {
                  pathPart = pathPart.slice(bName.length + 1);
                }
                if (pathPart.endsWith(".mp4")) {
                  outputKey = pathPart;
                }
              } catch {
              }
            }
            finalUrl = await (0, import_s3_request_presigner.getSignedUrl)(s3, new import_client_s313.GetObjectCommand({
              Bucket: bName,
              Key: outputKey
            }), { expiresIn: 7200 });
          } catch (e5) {
            console.warn("Presigned URL fallback notice:", e5.message);
          }
          return {
            statusCode: 200,
            headers,
            body: JSON.stringify({
              id: rawId,
              status: "complete",
              progress: 100,
              videoUrl: finalUrl,
              message: "Your cartoon cooking video is ready to watch and download!"
            })
          };
        }
        const pct = Math.max(5, Math.min(95, Math.round(progress.overallProgress * 100)));
        return {
          statusCode: 200,
          headers,
          body: JSON.stringify({
            id: rawId,
            status: "rendering",
            progress: pct,
            message: `Chef Maya is animating your recipe (${pct}%)...`
          })
        };
      } catch (progressError) {
        console.error("Progress check error:", progressError);
        return {
          statusCode: 200,
          headers,
          body: JSON.stringify({
            id: rawId,
            status: "failed",
            progress: 0,
            message: `Cloud render check error: ${progressError.message || String(progressError)}`
          })
        };
      }
    }
    return {
      statusCode: 404,
      headers,
      body: JSON.stringify({ error: "Endpoint not found" })
    };
  } catch (fatalError) {
    console.error("Fatal Lambda error:", fatalError);
    return {
      statusCode: 500,
      headers,
      body: JSON.stringify({
        error: `Cloud Studio error: ${fatalError.message || String(fatalError)}`
      })
    };
  }
}
export {
  handler
};
